 66	    function Invoke-Scoop {
 67	        param(
 68	            [Parameter(Mandatory = $true, ValueFromRemainingArguments = $true)]
 69	            [string[]] $ScoopArgs
 70	        )
 71	
 72	        # Native stderr redirected with 2>&1 becomes ErrorRecord. With
 73	        # $ErrorActionPreference Stop that is terminating even when scoop
 74	        # exits 0 (update notices, deprecation warnings).
 75	        $previous = $ErrorActionPreference
 76	        $ErrorActionPreference = "Continue"
 77	        try {
 78	            $output = & "scoop" @ScoopArgs 2>&1
 79	            return @{
 80	                ExitCode = [int] $LASTEXITCODE
 81	                Output   = $output
 82	            }
 83	        }
 84	        finally {
 85	            $ErrorActionPreference = $previous
 86	        }
