127	    function Get-PlatformArchitecture {
128	        # The machine-level value is the native OS architecture. The
129	        # $env:PROCESSOR_ARCHITECTURE seen by the script is the process's, so
130	        # x64 PowerShell on ARM64 Windows reports AMD64. RuntimeInformation is
131	        # not an option either: it needs .NET 4.7.1+, so it is missing on
132	        # stock Windows PowerShell 5.1 installs.
133	        $environmentKey = "HKLM:\SYSTEM\CurrentControlSet\Control\Session Manager\Environment"
134	        $architecture = (Get-ItemProperty -LiteralPath $environmentKey -Name "PROCESSOR_ARCHITECTURE").PROCESSOR_ARCHITECTURE
135	
136	        if ([string]::IsNullOrWhiteSpace($architecture)) {
137	            throw "Cannot determine the Windows architecture."
138	        }
139	
140	        switch ($architecture.ToUpperInvariant()) {
141	            "AMD64" { return "amd64" }
142	            "ARM64" { return "arm64" }
143	            default { throw "Unsupported architecture: $architecture" }
144	        }
145	    }
