163	    function Get-ReleaseVersion {
164	        param([string] $ReleaseChannel)
165	
166	        if ($ReleaseChannel -eq "nightly") {
167	            $uri = "https://api.github.com/repos/$GitHubRepo/releases?per_page=20"
168	            $releases = Invoke-GitHubApi -Uri $uri
169	            $release = $null
170	
171	            # GitHub returns created_at descending. The first *nightly* tag is
172	            # the latest nightly. Windows PowerShell 5.1 returns a JSON array
173	            # from Invoke-RestMethod as one pipeline object, so enumerate it
174	            # explicitly instead of piping to Where-Object.
175	            foreach ($candidate in $releases) {
176	                if ($candidate.tag_name -like "*nightly*") {
177	                    $release = $candidate
178	                    break
179	                }
180	            }
181	        }
182	        else {
183	            $uri = "https://api.github.com/repos/$GitHubRepo/releases/latest"
184	            $release = Invoke-GitHubApi -Uri $uri
185	        }
186	
187	        if ($null -eq $release -or [string]::IsNullOrWhiteSpace([string] $release.tag_name)) {
188	            throw "Failed to fetch the latest $ReleaseChannel version from GitHub. Check your internet connection."
189	        }
190	
191	        $version = ([string] $release.tag_name) -replace "^v", ""
192	        if ($version -notmatch "^[0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$") {
193	            throw "GitHub returned an invalid release version: $version"
194	        }
195	
196	        return $version
197	    }
