210	    function Assert-Checksum {
211	        param(
212	            [string] $ArchivePath,
213	            [string] $ArchiveName,
214	            [string] $ChecksumsPath
215	        )
216	
217	        $escapedArchiveName = [regex]::Escape($ArchiveName)
218	        $checksumLine = Get-Content -LiteralPath $ChecksumsPath |
219	            Where-Object { $_ -match "(?i)^[0-9a-f]{64}\s+\*?$escapedArchiveName\s*$" } |
220	            Select-Object -First 1
221	
222	        if ([string]::IsNullOrWhiteSpace([string] $checksumLine)) {
223	            throw "Checksum for $ArchiveName was not found in checksums.txt."
224	        }
225	
226	        $expectedChecksum = ([string] $checksumLine -split "\s+")[0]
227	        $actualChecksum = (Get-FileHash -LiteralPath $ArchivePath -Algorithm SHA256).Hash
228	        if (-not [string]::Equals($actualChecksum, $expectedChecksum, [StringComparison]::OrdinalIgnoreCase)) {
229	            throw "Checksum verification failed. Expected: $expectedChecksum, actual: $actualChecksum"
230	        }
231	    }
