233	    function Get-NormalizedPath {
234	        param([string] $Path)
235	
236	        # Resolve against $PWD and expand ~. [IO.Path]::GetFullPath alone uses
237	        # [Environment]::CurrentDirectory, which Windows PowerShell 5.1 does
238	        # not keep in sync with Set-Location, and does not expand ~.
239	        $fullPath = [IO.Path]::GetFullPath(
240	            $ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($Path)
241	        )
242	        $root = [IO.Path]::GetPathRoot($fullPath)
243	        if ([string]::Equals($fullPath, $root, [StringComparison]::OrdinalIgnoreCase)) {
244	            return $root
245	        }
246	
247	        [char[]] $separators = @(
248	            [IO.Path]::DirectorySeparatorChar,
249	            [IO.Path]::AltDirectorySeparatorChar
250	        )
251	        return $fullPath.TrimEnd($separators)
252	    }
