316	    function Get-PathWithDirectoryFirst {
317	        param(
318	            [AllowNull()]
319	            [string] $PathValue,
320	            [string] $Directory
321	        )
322	
323	        $parts = New-Object System.Collections.Generic.List[string]
324	        if (-not [string]::IsNullOrWhiteSpace($PathValue)) {
325	            foreach ($entry in ($PathValue -split ";")) {
326	                $trimmed = $entry.Trim()
327	                if ([string]::IsNullOrWhiteSpace($trimmed)) {
328	                    continue
329	                }
330	                if (-not (Test-SamePath -Left $trimmed -Right $Directory)) {
331	                    $parts.Add($trimmed)
332	                }
333	            }
334	        }
335	        if ($parts.Count -eq 0) {
336	            return $Directory
337	        }
338	        return "$Directory;" + ($parts -join ";")
