342	        param([string] $Directory)
343	
344	        $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
345	        $userPathChanged = $false
346	        if (-not (Test-PathIsFirst -PathValue $userPath -Directory $Directory)) {
